import React, { useEffect, useState, useCallback } from 'react';
import reservationService from '../../services/reservationService';
import PageHeader from '../../components/common/PageHeader';
import StatusBadge from '../../components/common/StatusBadge';
import '../../components/common/shared.css';
import './CheckInOutPage.css';

// ✅ FIX : Le backend retourne les champs en camelCase (checkInDate, checkOutDate)
// ET le statut en UPPERCASE (CONFIRMED, CHECKED_IN, etc.)
// Ces helpers normalisent les deux cas pour être robustes

/** Retourne la date d'arrivée quelle que soit la casse du champ */
const getCheckIn  = (r) => r.checkInDate  ?? r.check_in  ?? '';
/** Retourne la date de départ quelle que soit la casse du champ */
const getCheckOut = (r) => r.checkOutDate ?? r.check_out ?? '';
/** Normalise le statut en lowercase pour les comparaisons */
const getStatus   = (r) => (r.status ?? '').toLowerCase();

const CheckInOutPage = ({ toast }) => {
  const [reservations, setReservations] = useState([]);
  const [loading, setLoading]           = useState(true);
  const [acting, setActing]             = useState(null);
  const [tab, setTab]                   = useState('checkin');

  const load = useCallback(() => {
    setLoading(true);
    reservationService.getAll()
      .then(data => {
        console.log('[CheckInOut] réservations reçues:', data);
        setReservations(data);
      })
      .catch(() => toast?.error('Impossible de charger les réservations'))
      .finally(() => setLoading(false));
  }, [toast]);

  useEffect(() => { load(); }, [load]);

  const todayStr = new Date().toISOString().split('T')[0]; // "YYYY-MM-DD"

  // ✅ FIX : utilise getCheckIn() et getStatus() pour gérer camelCase + UPPERCASE
  const arrivals = reservations.filter(r =>
    getCheckIn(r).startsWith(todayStr) &&
    getStatus(r) === 'confirmed'
  );

  const departures = reservations.filter(r =>
    getCheckOut(r).startsWith(todayStr) &&
    getStatus(r) === 'checked_in'
  );

  const handleCheckIn = async (id) => {
    setActing(id);
    try {
      await reservationService.checkIn(id);
      toast?.success('Check-in effectué');
      load();
    } catch (err) {
      toast?.error(err.message || 'Erreur check-in');
    } finally {
      setActing(null);
    }
  };

  const handleCheckOut = async (id) => {
    setActing(id);
    try {
      await reservationService.checkOut(id);
      toast?.success('Check-out effectué');
      load();
    } catch (err) {
      toast?.error(err.message || 'Erreur check-out');
    } finally {
      setActing(null);
    }
  };

  // ✅ FIX : helper nom client robuste (camelCase ou snake_case)
  const clientName = (r) =>
    r.client?.fullName ||
    (r.client ? [r.client.firstName, r.client.lastName].filter(Boolean).join(' ') : null) ||
    r.client?.name ||
    `Client #${r.clientId ?? r.client_id}`;

  // ✅ FIX : helper numéro chambre robuste
  const roomNumber = (r) =>
    r.room?.number ?? r.roomId ?? r.room_id;

  // ✅ FIX : formatage date robuste (accepte checkInDate ou check_in)
  const formatDate = (dateStr) => {
    if (!dateStr) return '—';
    try { return new Date(dateStr).toLocaleDateString('fr-FR'); }
    catch { return dateStr; }
  };

  const list = tab === 'checkin' ? arrivals : departures;

  return (
    <div>
      <PageHeader
        title="Check-in / Check-out"
        subtitle="Gérer les arrivées et départs du jour"
      />

      {/* Tabs */}
      <div className="cio-tabs">
        <button
          className={`cio-tab ${tab === 'checkin' ? 'cio-tab--active' : ''}`}
          onClick={() => setTab('checkin')}
        >
          <span className="cio-tab__count">{arrivals.length}</span>
          Arrivées aujourd'hui
        </button>
        <button
          className={`cio-tab ${tab === 'checkout' ? 'cio-tab--active' : ''}`}
          onClick={() => setTab('checkout')}
        >
          <span className="cio-tab__count">{departures.length}</span>
          Départs aujourd'hui
        </button>
      </div>

      {loading ? (
        <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-muted)' }}>
          Chargement…
        </div>
      ) : list.length === 0 ? (
        <div className="cio-empty">
          {tab === 'checkin'
            ? "Aucune arrivée prévue aujourd'hui."
            : "Aucun départ prévu aujourd'hui."
          }
        </div>
      ) : (
        <div className="cio-list">
          {list.map(r => (
            <div key={r.id} className="cio-card">
              <div className="cio-card__info">
                <div className="cio-card__avatar">
                  {clientName(r).charAt(0).toUpperCase()}
                </div>
                <div>
                  <p className="cio-card__name">{clientName(r)}</p>
                  <p className="cio-card__meta">
                    Chambre {roomNumber(r)}
                    {' · '}
                    {formatDate(getCheckIn(r))}
                    {' → '}
                    {formatDate(getCheckOut(r))}
                  </p>
                  {r.guests && (
                    <p className="cio-card__guests">
                      {r.guests} personne{r.guests > 1 ? 's' : ''}
                    </p>
                  )}
                </div>
              </div>
              <div className="cio-card__right">
                <StatusBadge status={r.status} />
                {tab === 'checkin' ? (
                  <button
                    className="btn btn--gold"
                    disabled={acting === r.id}
                    onClick={() => handleCheckIn(r.id)}
                  >
                    {acting === r.id ? <span className="dt-spinner" /> : '✓ Check-in'}
                  </button>
                ) : (
                  <button
                    className="btn btn--primary"
                    disabled={acting === r.id}
                    onClick={() => handleCheckOut(r.id)}
                  >
                    {acting === r.id ? <span className="dt-spinner" /> : '⎋ Check-out'}
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default CheckInOutPage;
